-- All ids are UUIDv7 generated by the application (time-ordered, so id order = creation order).
-- All money is bigint minor units (cents). Status columns are text + CHECK rather than
-- Postgres enums so adding a value later is a plain constraint change.

CREATE TABLE businesses (
    id         uuid PRIMARY KEY,
    name       text NOT NULL,
    email      text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE api_keys (
    id           uuid PRIMARY KEY,
    business_id  uuid NOT NULL REFERENCES businesses (id),
    prefix       text NOT NULL UNIQUE,            -- public part, used for lookup and logs
    key_hash     bytea NOT NULL,                  -- sha256(full key); plaintext is never stored
    revoked_at   timestamptz,                     -- null = active; rows are never deleted
    last_used_at timestamptz,
    created_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX api_keys_business_idx ON api_keys (business_id, id);

CREATE TABLE customers (
    id          uuid PRIMARY KEY,
    business_id uuid NOT NULL REFERENCES businesses (id),
    name        text NOT NULL,
    email       text NOT NULL,
    created_at  timestamptz NOT NULL DEFAULT now(),
    UNIQUE (business_id, email),
    UNIQUE (business_id, id)                      -- target of the composite FK from invoices; also serves listing
);

CREATE TABLE invoices (
    id                      uuid PRIMARY KEY,
    business_id             uuid NOT NULL,
    customer_id             uuid NOT NULL,
    status                  text NOT NULL CHECK (status IN ('draft', 'open', 'paid', 'void', 'uncollectible')),
    currency                text NOT NULL DEFAULT 'USD' CHECK (currency = 'USD'),
    total_cents             bigint NOT NULL CHECK (total_cents >= 0),
    due_date                timestamptz NOT NULL,
    version                 bigint NOT NULL DEFAULT 0,    -- optimistic concurrency: every mutation bumps it
    created_at              timestamptz NOT NULL DEFAULT now(),
    updated_at              timestamptz NOT NULL DEFAULT now(),
    finalized_at            timestamptz,
    paid_at                 timestamptz,
    voided_at               timestamptz,
    marked_uncollectible_at timestamptz,
    -- An invoice can only reference a customer of the same business.
    FOREIGN KEY (business_id, customer_id) REFERENCES customers (business_id, id)
);
CREATE INDEX invoices_business_idx ON invoices (business_id, id);
CREATE INDEX invoices_business_status_idx ON invoices (business_id, status, id);
CREATE INDEX invoices_customer_idx ON invoices (business_id, customer_id, id);

CREATE TABLE invoice_line_items (
    id                uuid PRIMARY KEY,
    invoice_id        uuid NOT NULL REFERENCES invoices (id),
    position          int NOT NULL CHECK (position >= 0),
    description       text NOT NULL CHECK (length(description) BETWEEN 1 AND 500),
    quantity          int NOT NULL CHECK (quantity BETWEEN 1 AND 10000),
    unit_amount_cents bigint NOT NULL CHECK (unit_amount_cents >= 0),
    amount_cents      bigint NOT NULL CHECK (amount_cents = quantity * unit_amount_cents),
    UNIQUE (invoice_id, position)
);

CREATE TABLE payment_attempts (
    id              uuid PRIMARY KEY,                 -- also the PSP `reference` (PSP-side idempotency)
    business_id     uuid NOT NULL,
    invoice_id      uuid NOT NULL REFERENCES invoices (id),
    amount_cents    bigint NOT NULL CHECK (amount_cents > 0),
    status          text NOT NULL CHECK (status IN ('pending', 'succeeded', 'failed')),
    card_token      text NOT NULL,
    psp_ref         text,
    failure_code    text,
    last_error      text,                             -- e.g. psp_timeout while the outcome is unknown
    idempotency_key text NOT NULL,
    created_at      timestamptz NOT NULL DEFAULT now(),
    completed_at    timestamptz
);
-- The database itself forbids a second successful charge and a second in-flight attempt.
CREATE UNIQUE INDEX payment_attempts_one_success_idx ON payment_attempts (invoice_id) WHERE status = 'succeeded';
CREATE UNIQUE INDEX payment_attempts_one_pending_idx ON payment_attempts (invoice_id) WHERE status = 'pending';
CREATE INDEX payment_attempts_invoice_idx ON payment_attempts (invoice_id, id);
CREATE INDEX payment_attempts_pending_idx ON payment_attempts (created_at) WHERE status = 'pending';

CREATE TABLE idempotency_keys (
    business_id   uuid NOT NULL,
    key           text NOT NULL,
    request_hash  bytea NOT NULL,                    -- sha256(method + path + canonical body)
    status        text NOT NULL CHECK (status IN ('in_progress', 'completed')),
    response_code int,
    response_body jsonb,
    created_at    timestamptz NOT NULL DEFAULT now(),
    expires_at    timestamptz NOT NULL,
    PRIMARY KEY (business_id, key)
);
CREATE INDEX idempotency_keys_expires_idx ON idempotency_keys (expires_at);

CREATE TABLE webhook_endpoints (
    id          uuid PRIMARY KEY,
    business_id uuid NOT NULL REFERENCES businesses (id),
    url         text NOT NULL,
    secret      text NOT NULL,                        -- plaintext: HMAC signing needs the raw value (see DESIGN.md §4)
    enabled     boolean NOT NULL DEFAULT true,
    created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX webhook_endpoints_business_idx ON webhook_endpoints (business_id) WHERE enabled;

CREATE TABLE events (
    id          uuid PRIMARY KEY,
    business_id uuid NOT NULL REFERENCES businesses (id),
    type        text NOT NULL,
    invoice_id  uuid NOT NULL,
    payload     jsonb NOT NULL,
    created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX events_business_idx ON events (business_id, id);

CREATE TABLE webhook_deliveries (
    id                 uuid PRIMARY KEY,
    event_id           uuid NOT NULL REFERENCES events (id),
    endpoint_id        uuid NOT NULL REFERENCES webhook_endpoints (id),
    status             text NOT NULL CHECK (status IN ('pending', 'delivered', 'failed')),
    attempt_count      int NOT NULL DEFAULT 0,
    next_attempt_at    timestamptz NOT NULL,
    last_response_code int,
    last_error         text,
    delivered_at       timestamptz,
    created_at         timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX webhook_deliveries_due_idx ON webhook_deliveries (next_attempt_at) WHERE status = 'pending';
CREATE INDEX webhook_deliveries_event_idx ON webhook_deliveries (event_id);
